import java.io.*;
import java.nio.file.*;
import javax.xml.XMLConstants;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.*;
public class DiameterkitShXSDCheck {
 public static void main(String[] args) throws Exception {
  SchemaFactory f=SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
  f.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING,true);
  f.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD,"");
  f.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");
  Schema s=f.newSchema(Path.of(args[0]).toFile());
  for(String line:Files.readAllLines(Path.of(args[1]))) {
   String[] a=line.split("\\t"); boolean valid=true;
   try { Validator v=s.newValidator();v.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD,"");v.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA,"");v.validate(new StreamSource(Path.of(a[1]).toFile())); }
   catch(org.xml.sax.SAXException e){valid=false;}
   if(valid!=a[0].equals("valid"))throw new Exception("unexpected XSD result: "+a[1]+" valid="+valid);
   System.out.println("PASS "+Path.of(a[1]).getFileName()+": XSD "+(valid?"valid":"invalid"));
  }
 }
}
